trap 'rm -rf "$TMP"' EXIT

"$TSHARK" -r "$CAP" -Y "$FILTER" -T fields \
  -e frame.number -e frame.time_relative -e usb.bmRequestType -e usb.endpoint_address \
  2>/dev/null > "$TMP/meta"

